import {
  DateInput as DateInputPrimitive,
  type DateInputDateValue,
  useDateInput,
  useDateInputContext,
} from '@ark-ui/solid/date-input';
import { clsx } from 'clsx';
import type { ComponentProps } from 'solid-js';
import { splitProps } from 'solid-js';
import styles from './DateInput.module.css';

function DateInput(props: ComponentProps<typeof DateInputPrimitive.Root>) {
  const [local, others] = splitProps(props, ['children', 'class']);

  return (
    <DateInputPrimitive.Root
      class={clsx(styles.root, local.class)}
      {...others}
      data-slot="date-input-root"
    >
      {local.children}
    </DateInputPrimitive.Root>
  );
}

function DateInputRootProvider(props: ComponentProps<typeof DateInputPrimitive.RootProvider>) {
  const [local, others] = splitProps(props, ['children', 'class']);

  return (
    <DateInputPrimitive.RootProvider
      class={clsx(styles.root, local.class)}
      {...others}
      data-slot="date-input-root-provider"
    >
      {local.children}
    </DateInputPrimitive.RootProvider>
  );
}

function DateInputLabel(props: ComponentProps<typeof DateInputPrimitive.Label>) {
  const [local, others] = splitProps(props, ['class']);

  return (
    <DateInputPrimitive.Label
      class={clsx(styles.label, local.class)}
      {...others}
      data-slot="date-input-label"
    />
  );
}

function DateInputControl(props: ComponentProps<typeof DateInputPrimitive.Control>) {
  const [local, others] = splitProps(props, ['class']);

  return (
    <DateInputPrimitive.Control
      class={clsx(styles.control, local.class)}
      {...others}
      data-slot="date-input-control"
    />
  );
}

function DateInputSegmentGroup(props: ComponentProps<typeof DateInputPrimitive.SegmentGroup>) {
  const [local, others] = splitProps(props, ['class']);

  return (
    <DateInputPrimitive.SegmentGroup
      class={clsx(styles.segmentGroup, local.class)}
      {...others}
      data-slot="date-input-segment-group"
    />
  );
}

function DateInputSegment(props: ComponentProps<typeof DateInputPrimitive.Segment>) {
  const [local, others] = splitProps(props, ['class']);

  return (
    <DateInputPrimitive.Segment
      class={clsx(styles.segment, local.class)}
      {...others}
      data-slot="date-input-segment"
    />
  );
}

type DateInputSegmentsProps = Omit<
  ComponentProps<typeof DateInputPrimitive.SegmentGroup>,
  'asChild' | 'children'
>;

function DateInputSegments(props: DateInputSegmentsProps) {
  return (
    <DateInputSegmentGroup {...props}>
      <DateInputPrimitive.SegmentContext>
        {(segment) => <DateInputSegment segment={segment} />}
      </DateInputPrimitive.SegmentContext>
    </DateInputSegmentGroup>
  );
}

function DateInputSeparator(props: ComponentProps<'span'>) {
  const [local, others] = splitProps(props, ['class']);

  return (
    <span
      aria-hidden="true"
      class={clsx(styles.separator, local.class)}
      {...others}
      data-slot="date-input-separator"
    />
  );
}

const DateInputHiddenInput = DateInputPrimitive.HiddenInput;
const DateInputContext = DateInputPrimitive.Context;
const DateInputSegmentContext = DateInputPrimitive.SegmentContext;

export {
  DateInput,
  DateInputContext,
  DateInputControl,
  DateInputHiddenInput,
  DateInputLabel,
  DateInputRootProvider,
  DateInputSegment,
  DateInputSegmentContext,
  DateInputSegmentGroup,
  DateInputSegments,
  DateInputSeparator,
  type DateInputDateValue,
  useDateInput,
  useDateInputContext,
};

export type {
  DateInputContextProps,
  DateInputControlProps,
  DateInputFocusChangeDetails,
  DateInputHiddenInputProps,
  DateInputLabelProps,
  DateInputPlaceholderChangeDetails,
  DateInputRootProps,
  DateInputRootProviderProps,
  DateInputSegmentContextProps,
  DateInputSegmentGroupProps,
  DateInputSegmentProps,
  DateInputSelectionMode,
  DateInputValueChangeDetails,
  UseDateInputContext,
  UseDateInputProps,
  UseDateInputReturn,
} from '@ark-ui/solid/date-input';

@layer moduix.components {
  .root {
    display: inline-flex;
    flex-direction: column;
    align-items: flex-start;
    gap: var(--moduix-spacing-1);
    width: var(--moduix-date-input-width, auto);
    max-width: 100%;

    &[data-disabled] {
      opacity: var(--moduix-opacity-disabled);

      :where(
          [data-slot='field-root'][data-disabled],
          [data-slot='field-root-provider'][data-disabled],
          [data-slot='fieldset-root'][data-disabled],
          [data-slot='fieldset-root-provider'][data-disabled]
        )
        & {
        opacity: 1;
      }
    }
  }

  .label {
    color: var(--moduix-color-foreground);
    font-size: var(--moduix-text-sm);
    font-weight: var(--moduix-weight-medium);
    line-height: var(--moduix-line-height-text-sm);
  }

  .control {
    box-sizing: border-box;
    display: flex;
    align-items: center;
    gap: var(--moduix-spacing-1);
    width: 100%;
    min-height: var(--moduix-date-input-control-height, var(--moduix-size-md));
    border: var(--moduix-border-width-sm) solid var(--moduix-color-border);
    border-radius: var(--moduix-date-input-radius, var(--moduix-radius-md));
    padding: var(--moduix-spacing-1) var(--moduix-spacing-3);
    background-color: var(--moduix-color-background);
    color: var(--moduix-color-foreground);
    font-size: var(--moduix-text-md);
    line-height: var(--moduix-line-height-text-md);
    outline: var(--moduix-focus-ring-inset-width) solid transparent;
    outline-offset: var(--moduix-focus-ring-inset-offset);
    transition:
      border-color var(--moduix-transition-default),
      outline-color var(--moduix-transition-default);

    &[data-focus] {
      outline-color: var(--moduix-color-ring);
    }

    &[data-invalid] {
      border-color: var(--moduix-color-destructive);

      &[data-focus] {
        outline-color: var(--moduix-color-destructive);
      }
    }

    &[data-disabled] {
      pointer-events: none;
    }
  }

  .segmentGroup {
    display: flex;
    align-items: center;
    gap: var(--moduix-spacing-0-5);
    font-variant-numeric: tabular-nums;
  }

  .segment {
    min-width: 2ch;
    border-radius: var(--moduix-radius-sm);
    padding-inline: var(--moduix-spacing-1);
    text-align: center;
    outline: 0;
    cursor: default;
    transition:
      background-color var(--moduix-transition-default),
      color var(--moduix-transition-default);

    &[data-editable] {
      cursor: text;
    }

    &[data-placeholder-shown] {
      color: var(--moduix-color-muted-foreground);
    }

    &:focus-visible {
      background-color: color-mix(in oklab, var(--moduix-color-ring) 18%, transparent);
      color: var(--moduix-color-foreground);
    }

    &[data-type='literal'] {
      min-width: auto;
      padding-inline: 0;
      color: var(--moduix-color-muted-foreground);
    }
  }

  .separator {
    color: var(--moduix-color-muted-foreground);
    user-select: none;
  }
}
